from pwn import *
import sys
import math

# Connect to the server
r = remote('mandf.csaw.io', 3000)

def send_sequence():
    # Part 1: Alternating 1 and -1 (10 numbers)
    sequence = []
    for i in range(10):
        sequence.append(1 if i % 2 == 0 else -1)

    # Part 2: Alternating max and min float (10 numbers)
    for i in range(10):
        if i % 2 == 0:
            sequence.append(sys.float_info.max)
        else:
            sequence.append(sys.float_info.min)

    # Part 3: Alternating specific large and small values (10 numbers)
    for i in range(10):
        if i % 2 == 0:
            sequence.append(1.23456789e+100)
        else:
            sequence.append(-9.87654321e-100)

    # Receive initial server output
    print(r.recvuntil(b'Enter your sequence:').decode())

    # Send each number in sequence
    for num in sequence:
        r.sendline(str(num).encode())
        response = r.recvline().decode().strip()
        print(f"Sent: {num}")
        print(f"Response: {response}")

    # Get final response
    final_response = r.recvall(timeout=2)
    print("Final response:", final_response.decode() if final_response else "No final response")

if __name__ == '__main__':
    send_sequence()

#!/usr/bin/python3
from pwn import *
import sys
import math

# Connect to the server
r = remote('mandf.csaw.io', 3000)

def send_sequence():
    # Receive initial output
    print(r.recvuntil(b'starting...').decode())

    # Part 1: Alternating 1 and -1 (10 numbers)
    sequence = []
    for i in range(10):
        sequence.append(1 if i % 2 == 0 else -1)

    # Part 2: Alternating max and min float (10 numbers)
    for i in range(10):
        if i % 2 == 0:
            sequence.append(sys.float_info.max)
        else:
            sequence.append(sys.float_info.min)

    # Part 3: Alternating specific large and small values (10 numbers)
    for i in range(10):
        if i % 2 == 0:
            sequence.append(1.23456789e+100)
        else:
            sequence.append(-9.87654321e-100)

    # Send each number and collect responses
    for idx, num in enumerate(sequence):
        r.sendline(str(num).encode())
        print(f"Sent ({idx+1}/30): {num}")
        try:
            response = r.recvline().decode().strip()
            print(f"Response: {response}")
        except EOFError:
            print("Connection closed by server")
            break

    # Try to get any final output
    try:
        final = r.recvall(timeout=3)
        if final:
            print("Final response:", final.decode())
    except:
        pass

if __name__ == '__main__':
    send_sequence()
    r.close()

