from pwn import *
import sys

# Connect to the server
conn = remote('mandf.csaw.io', 3000)

# Receive initial banner
print(conn.recvuntil(b'prediction:').decode())

# Generate our sequence
sequence = []
# Part 1: Alternating 1 and -1
for i in range(10):
    sequence.append('1' if i % 2 == 0 else '-1')

# Part 2: Max and min floats (using scientific notation)
for i in range(10):
    if i % 2 == 0:
        sequence.append('1.8e+308')  # Close to max float
    else:
        sequence.append('2.2e-308')  # Close to min float

# Part 3: Specific large and small numbers
for i in range(10):
    if i % 2 == 0:
        sequence.append('1.23456789e+100')
    else:
        sequence.append('-9.87654321e-100')

# Send sequence
for num in sequence:
    conn.sendline(num.encode())
    try:
        response = conn.recvline().decode().strip()
        print(f"Sent: {num}")
        print(f"Response: {response}")
    except:
        pass

# Try to get final response
try:
    while True:
        line = conn.recvline().decode().strip()
        if line:
            print("Server:", line)
except:
    pass

conn.close()
